fn transpose(arr: Vec<Vec<i8>>) -> Vec<Vec<i8>> {
    // Get the number of rows and columns from the input matrix
    let num_rows = arr.len();
    let num_cols = arr[0].len();
    
    // Initialize the output matrix with the transposed dimensions
    let mut transposed = vec![vec![0; num_rows]; num_cols];
    
    // Fill the transposed matrix
    for i in 0..num_rows {
        for j in 0..num_cols {
            transposed[j][i] = arr[i][j];
        }
    }
    
    transposed
}